    scans=[{'directory':p.name,'classification':'game depth dossier' if p.name in SPEC else 'shared game-source dossier' if p.name in ['open-idle-games-2026-10-09','game-discovery-2026-10-06','idle-social-engine-scout-2026-10-06','free-text-worlds-2026-10-14','repository-bank'] else 'routing audit, thematic/source-library, wave index, tooling or non-game reference; not another game depth dossier'} for p in sorted(R.iterdir()) if p.is_dir() and p!=OUT]
