    payload={'schema_version':1,'date':datetime.now().astimezone().isoformat(),'owner':'deep-detail-reaudit-2026-10-14','scope':'One row per named game; aggregate snapshots may serve several game rows. Public-document and retired rows retained explicitly, not counted as source-depth passes. Non-game engines/toolkits are directory exclusions.',
             'method':'Current owner document readback plus local-path and finished-lane snapshot inspection. Earlier source conclusions are inherited and qualified, not independently replayed. No new source-game decompile, launch or adoption audit. Preservation hashes verify copied bytes only.',
             'counts':{'game_rows':len(expanded),'in_scope':sum(x['scope']=='in-scope' for x in expanded),'deferred_live_lane':sum(x['scope']=='deferred' for x in expanded),'public_docs_only':sum(x['scope']=='public-docs-only' for x in expanded),'seed_source_only':sum(x['scope']=='seed-source-only' for x in expanded),'retired':sum(x['scope']=='retired-identity' for x in expanded),'private_snapshot_dossiers':len(receipts)},
             'direction_and_routing_inputs':evidence,'live_process_observations':processes,'session_registries':sessions,'steam_inventory':steam_inventory(),
             'local_inventory_limits':'Recorded research roots, supplied DMGs, known scratch source paths, one declared Steam library, Applications/Games top-level and targeted transfer-archive file names checked. No whole-disk absence claim; no saves/userdata/compatdata contents read.',
             'directory_census':scans,'rows':expanded}
